insert into pb_ai.eval_runs(run, fn, label, k, ids, cases)
with c as (select e->>0 id, e->>1 q1, e->>2 wh, e->>3 lv, e->>4 rp, o from jsonb_array_elements($j$[["fu7-01", "What slope do I cut in Type B soil, and what are my options instead of sloping?", "Phoenix, AZ", "pipelayer", "yes please"], ["fu7-02", "Can we bench a trench in Type C soil, and what are the benching rules?", "Dallas, TX", "pipelayer", "ok go ahead"], ["fu7-03", "How do I size timber shoring for a 10 foot deep trench in Type B soil?", "Columbus, OH", "foreman", "yes"], ["fu7-04", "How do I set up hydraulic shores in an 8 foot trench in Type C soil?", "Denver, CO", "foreman", "sure"], ["fu7-05", "How do I set up a lane closure on a 45 mph two-lane road for a sewer tie-in?", "Tulsa, OK", "foreman", "yes"], ["fu7-06", "What sign spacing do I need for a work zone on a 55 mph highway?", "Little Rock, AR", "foreman", "keep going"], ["fu7-07", "How long does the merging taper have to be for a lane closure on a 40 mph road with 12 foot lanes?", "Boise, ID", "foreman", "yes"], ["fu7-08", "We have to close the sidewalk for the trench. What do we have to do for people walking?", "Minneapolis, MN", "foreman", "yes"], ["fu7-09", "Where do the flaggers go and what signs do we need for one-lane flagging on a 35 mph road?", "Raleigh, NC", "foreman", "go on"], ["fu7-10", "What are the steps to issue a confined space entry permit for a manhole?", "Columbus, OH", "foreman", "go on"], ["fu7-11", "What has to be on a confined space entry permit?", "Atlanta, GA", "foreman", "sure"], ["fu7-12", "What order do we test the air in a manhole, and what are the limits?", "Detroit, MI", "foreman", "yes"], ["fu7-13", "How do we set up rescue for a sewer manhole entry?", "Nashville, TN", "foreman", "more"], ["fu7-14", "How do I renew my 811 ticket when the job runs long?", "Las Vegas, NV", "foreman", "yes"], ["fu7-15", "Our Texas811 ticket is about to run out and we are not done. What do we do?", "Houston, TX", "foreman", "go ahead"], ["fu7-16", "How do I bed PVC sewer pipe in the trench?", "Reno, NV", "pipelayer", "yes"], ["fu7-17", "How do I pressure test a new PVC water main?", "Omaha, NE", "foreman", "yeah"], ["fu7-18", "How do I disinfect a new water main before it goes in service?", "Boise, ID", "foreman", "more"], ["fu7-19", "What do we have to do for heat on a trench crew in summer?", "Bakersfield, CA", "foreman", "yes"], ["fu7-20", "How do I pick a trench box for a 12 foot deep sewer trench?", "Nashville, TN", "foreman", "yes"], ["fu7-21", "What are all the trench rules for a 6 foot deep trench?", "Orlando, FL", "foreman", "yes"], ["fu7-22", "We are cutting concrete pipe with a saw. What does the silica rule want us to do?", "Chicago, IL", "foreman", "yes"], ["fu7-23", "How close can the excavator work to an overhead power line?", "Atlanta, GA", "foreman", "go on"], ["fu7-24", "What do I need to do for the SWPPP on the job?", "Denver, CO", "office", "yes"], ["fu7-25", "How do I set up traffic control for night work on a pipe job?", "Phoenix, AZ", "foreman", "yes"], ["fu7-26", "How do I figure the thrust block for a 90 degree bend on an 8 inch water main?", "Fresno, CA", "foreman", "sure"], ["fu7-27", "What does the competent person have to do on an excavation?", "Tulsa, OK", "foreman", "go on"]]$j$::jsonb) with ordinality t(e, o)),
 j as (select c.*, (row_number() over (order by o) - 1) / 1 g, jsonb_build_object('id', c.id || '-t2', 'q', c.rp, 'where', c.wh, 'level', c.lv,
   'history', jsonb_build_array(jsonb_build_object('q', c.q1, 'a', r.text))) cs from c join pb_ai.eval_results r on r.run = '1121-lib8-fu1' and r.id = c.id || '-t1')
select '1121-lib8-fu2', 'ai-next', 'lib7 follow-through turn 2', g, array_agg(id || '-t2'), jsonb_agg(cs order by o) from j group by g;
select pb_ai.eval_pump('1121-lib8-fu2') started, (select count(*) from pb_ai.eval_runs where run = '1121-lib8-fu2') batches;
